(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-3-inner-ear-hearing-loss-vignettes-version-2"]={"title":"Inner Ear and Hearing Loss Vignettes 2 — CMS I Exam 3","category":"Clinical Medicine and Surgery I","exam":"Exam 3","sem":"fall-2026","questions":[{"q":"A 60-year-old woman is referred for formal hearing assessment. Single tones are presented at set frequencies and she signals the softest she can hear. Which test is this?","choices":["Electronystagmography","The Rinne test","Pure tone audiometry","Tympanometry"],"answer":2,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 8"},{"q":"A 68-year-old woman's audiogram shows thresholds of fifty decibels bilaterally. How is her loss classified?","choices":["Moderate","Mild","Profound","Normal"],"answer":0,"exp":"Correct — the forty to sixty band. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 19"},{"q":"A 22-year-old sound engineer whose hearing recovers by the next day after every shift asks whether that means he is safe. What should he be told?","choices":["Repeated exposure makes the loss permanent","Full recovery means no damage is accumulating","Only exposures causing pain matter","Hearing protection is unnecessary below one hundred decibels"],"answer":0,"exp":"Correct — the temporary shift is a warning, not reassurance. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 54"},{"q":"A 54-year-old woman has one-sided hearing loss and understands words far worse than her tone thresholds would predict, with some unsteadiness. Which study should be ordered?","choices":["The Dix-Hallpike manoeuvre","Magnetic resonance imaging with gadolinium","Tympanometry","Plain radiography"],"answer":1,"exp":"Correct — the gold standard for retrocochlear disease. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 75"},{"q":"A 38-year-old woman has sudden vertigo and reduced hearing on one side, lasting four days. She is afebrile. What treatment is appropriate?","choices":["Symptomatic treatment with meclizine","Immediate antibiotics","The Epley manoeuvre","A hearing aid immediately"],"answer":0,"exp":"Correct — antibiotics are added only if bacterial features appear. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 95"},{"q":"A 75-year-old man's audiogram is normal at low frequencies and drops steeply above two thousand hertz in both ears. What does this pattern indicate?","choices":["A conductive loss from wax","Otosclerosis","A middle ear effusion","Age-related sensorineural loss"],"answer":3,"exp":"Correct — a sloping high-frequency loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 19"},{"q":"A 39-year-old woman has confirmed syphilitic sensorineural hearing loss. What treatment is given?","choices":["Observation","An antibiotic with systemic corticosteroids","A hearing aid alone","An antifungal"],"answer":1,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 68"},{"q":"A 60-year-old man has a positive Dix-Hallpike test on the right. What treatment follows?","choices":["A hearing aid","The Epley manoeuvre","A course of oral antibiotics","Bed rest for two weeks"],"answer":1,"exp":"Correct — it repositions the debris in the canal. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 93"},{"q":"A 40-year-old diver has sudden hearing loss and vertigo after a dive, with a popping sensation at onset. What is appropriate management?","choices":["Antibiotic drops","Symptomatic treatment and specialist referral","Reassurance alone","The Epley manoeuvre"],"answer":1,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 64"},{"q":"A 60-year-old man has a small acoustic neuroma with mild symptoms. Which options should be discussed?","choices":["Tympanostomy tubes","Observation with annual imaging, surgery or radiation","Antibiotics alone","Ear drops alone"],"answer":1,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 75"},{"q":"A 70-year-old woman with vertigo also has a new headache and cannot walk in a straight line. What should be done?","choices":["Treat as positional vertigo","Prescribe meclizine and review in a month","Arrange a hearing aid","Refer urgently for neuroimaging"],"answer":3,"exp":"Correct — ataxia and headache with vertigo are warning features. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 78"},{"q":"A 30-year-old woman with a blocked ear speaks unusually softly during the consultation. What does this suggest about her hearing loss?","choices":["It is profound and bilateral","It is conductive","It is sensorineural","It is functional"],"answer":1,"exp":"Correct — she hears her own voice well because the inner ear is intact. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 42"},{"q":"A 39-year-old man reports right ear fullness and reduced hearing that began after a head cold. He denies ringing, dizziness, fever and discharge. An amber effusion is visible behind an intact right drum, which moves poorly. The left ear is normal. Which tuning fork findings are most likely?","choices":["Weber to the right; right air conduction greater than bone","No lateralisation; air conduction greater than bone bilaterally","Weber to the right; right bone conduction at least equal to air","Weber to the left; right air conduction greater than bone"],"answer":2,"exp":"Correct. A right middle ear effusion is a conductive loss, so Weber lateralises to it and Rinne becomes abnormal there. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 42"},{"q":"A 4-year-old girl has bilateral sensorineural hearing loss, a white forelock and eyes of different colours. Which condition does this suggest?","choices":["Alport syndrome","Meniere disease","Presbycusis","Waardenburg syndrome"],"answer":3,"exp":"Correct — one of the named hereditary causes. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 71"},{"q":"A 47-year-old woman describes ringing in the right ear only, which she can hear beating in time with her pulse. What is the appropriate response?","choices":["Investigate further","Reassure her that this is normal head noise","Advise her to avoid quiet rooms","Arrange review in one year"],"answer":0,"exp":"Correct — unilateral and pulsatile tinnitus are both red flags. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 45"},{"q":"A 64-year-old man treated with intravenous gentamicin for two weeks develops hearing loss in both ears. His canals and drums are normal. What is the most likely cause?","choices":["Acoustic neuroma","Ototoxicity","Presbycusis","Otosclerosis"],"answer":1,"exp":"Correct — aminoglycosides are the most ototoxic and the most commonly implicated. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 52"},{"q":"A 46-year-old woman has hearing loss in the left ear and a whooshing noise in time with her heartbeat. A reddish mass is visible behind the left drum. What is the most likely diagnosis?","choices":["Cholesteatoma","Middle ear effusion","Acoustic neuroma","Glomus tumour"],"answer":3,"exp":"Correct — a vascular middle ear mass with pulsatile tinnitus. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 50"},{"q":"A 55-year-old woman developed hearing loss in one ear ten days ago. Which treatment may still help?","choices":["Antibiotic ear drops","Observation for six months","Corticosteroids","A hearing aid alone"],"answer":2,"exp":"Correct — acute sensory loss may respond within the first weeks. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 13"},{"q":"A 55-year-old woman reports positional spinning attacks that each last twenty minutes. What should this prompt?","choices":["Starting a diuretic","Referral for a hearing aid","Considering an alternative diagnosis","Immediate Epley treatment"],"answer":2,"exp":"Correct — beyond a minute, positional vertigo becomes unlikely. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 91"},{"q":"A 48-year-old man wakes with profound hearing loss in the right ear. The canal and drum are normal and there is no wax. What is the appropriate action?","choices":["Review in six weeks","Prescribe antibiotic drops","Reassure and take no action","Refer to a specialist today"],"answer":3,"exp":"Correct — the corticosteroid window is short. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 79"},{"q":"A 29-year-old man claims profound hearing loss in both ears following a workplace dispute, yet speaks at a normal volume with normal articulation. What should be suspected?","choices":["Bilateral wax impaction","Ototoxicity","A functional hearing loss","Profound sensorineural loss"],"answer":2,"exp":"Correct — the normal voice does not fit the claimed loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 80"},{"q":"A 28-year-old man is told his hearing loss is conductive. What should he be told about the outlook?","choices":["It is often correctable","It is never correctable","It always progresses to deafness","It always requires a cochlear implant"],"answer":0,"exp":"Correct — that is the key difference from sensorineural loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 11"},{"q":"A 9-year-old boy has sensorineural hearing loss and blood in his urine. Which hereditary condition should be considered?","choices":["Alport syndrome","Usher syndrome","Meniere disease","Otosclerosis"],"answer":0,"exp":"Correct — hearing loss with kidney involvement. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 71"},{"q":"A 58-year-old woman is starting a prolonged aminoglycoside course. Which monitoring is required?","choices":["Peak drug levels","Weekly tympanometry","Daily otoscopy","No monitoring is needed"],"answer":0,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 52"},{"q":"A 52-year-old woman has reduced hearing on the left. A tuning fork on the forehead is loudest on the left, and on the left bone conduction exceeds air conduction. Which diagnosis best fits?","choices":["Ototoxicity","Meniere disease","Cerumen impaction","Presbycusis"],"answer":2,"exp":"Correct. These findings are conductive, and wax is a conductive cause. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 42"},{"q":"A 40-year-old woman with a normal-looking drum and conductive hearing loss has a tympanogram with normal pressure but unusually low compliance. What does this suggest?","choices":["Ossicular discontinuity","Middle ear fluid","A normal middle ear","Ossicular fixation"],"answer":3,"exp":"Correct — a shallow type As trace, fitting otosclerosis. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 28"},{"q":"A 62-year-old man treated for positional vertigo asks why he still feels unsteady hours later. What should he be told?","choices":["Imbalance can persist for hours after an episode","This means the treatment failed","This indicates a stroke","This is a side effect of the manoeuvre"],"answer":0,"exp":"Correct, and chronic balance complaints are common. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 92"},{"q":"A 55-year-old man with longstanding bilateral tinnitus asks what medication will cure it. What should he be told?","choices":["Diuretics eliminate it","Antihistamines are first-line","No drug has proved better than placebo","A short antibiotic course will clear it"],"answer":2,"exp":"Correct — masking and biofeedback may help instead. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 46"},{"q":"A 50-year-old woman with episodic vertigo has an audiogram showing loss confined to the low frequencies, which improves between attacks. What does this pattern suggest?","choices":["Presbycusis","Otosclerosis","Acoustic neuroma","Meniere disease"],"answer":3,"exp":"Correct — low-frequency, fluctuating sensorineural loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 69"},{"q":"A 36-year-old man has dramatic sudden vertigo with nausea and unsteadiness. His hearing is normal and there are no focal neurological findings. What should he be told about the outlook?","choices":["It will recur every week indefinitely","It is benign and self-limiting","It requires urgent surgery","It indicates a brain tumour"],"answer":1,"exp":"Correct, though balance symptoms may last months. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 96"}]};
